CREATE    VIEW [FO].[vwInventProcurementLedgerPostingDefinition]
AS
SELECT 
	[MainAccount],
	[ProductCategoryName],
	CAST ((CASE INVENTORYACCOUNTTYPE    
		WHEN 0 THEN 0 
		WHEN 1 THEN 1 
		WHEN 50 THEN 110
		WHEN 2 THEN 2 
		WHEN 250 THEN 250 
		WHEN 5 THEN 27 
		WHEN 6 THEN 28 
		WHEN 7 THEN 29 
		WHEN 3 THEN 3 
		WHEN 8 THEN 32 
		WHEN 9 THEN 33 
		WHEN 10 THEN 34 
		WHEN 11 THEN 35 
		WHEN 4 THEN 4 
		WHEN 53 THEN 51
		WHEN 55 THEN 62
		WHEN 54 THEN 63 
		ELSE 0 
	END) AS INT) AS INVENTORYACCOUNTTYPE,
	[ProductGroupId],
	[DataAreaId],
	[RecId]
FROM [synapse_fo].[vwINVENTPROCUREMENTLEDGERPOSTINGDEFINITION]
